_UNIT_BYTES = {
    "b": 1.0,
    "kb": 1024.0,
    "kib": 1024.0,
    "mb": 1024.0 ** 2,
    "mib": 1024.0 ** 2,
    "gb": 1024.0 ** 3,
    "gib": 1024.0 ** 3,
}

# pip / rich progress lines (may arrive with \\r instead of \\n)
_RE_DOWNLOADING = re.compile(
    r"Downloading\s+(\S+)\s+\(([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)\)",
    re.I,
)
_RE_PROGRESS = re.compile(
    r"([0-9.]+)\s*/\s*([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)"
    r"(?:\s+([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)/s)?",
    re.I,
)

# Direct package names (extras may be unavailable when installed from a frozen wheel).
# numpy must stay <2.5 so funasr→librosa→numba can use binary wheels (numba requires numpy<2.5).
EXTRA_PACKAGES: dict[str, tuple[str, ...]] = {
    # Hard native deps of faster-whisper must be named explicitly: bundled /
    # direct-whl installs use --no-deps, so transitive deps never arrive alone.
    # onnxruntime: Silero VAD (CPU EP). Satisfied by either onnxruntime or
    # onnxruntime-gpu (see _onnxruntime_importable / _requirement_satisfied).
    "asr-whisper": (
        "faster-whisper>=1.1.0",
        "ctranslate2>=4.0.0",
        "av>=10.0.0",
        "onnxruntime>=1.14.0,<1.22",
        "numpy>=1.24.0,<2.5",
    ),
    # funasr is also installed --no-deps via known wheels; list runtime imports
    # that SenseVoice / fsmn-vad need beyond torch. setuptools restores
    # distutils on Python 3.12+ (FunASR still imports it during auto-register).
    "asr-sensevoice": (
        "numpy>=1.24.0,<2.5",
        "numba",
        "llvmlite",
        "funasr>=1.1.0",
        "torch",
        "torchaudio",
        "setuptools>=69",
        "scipy>=1.4.1",
        "librosa",
        "soundfile>=0.12.1",
        "jieba",
        "kaldiio>=2.17.0",
        "jaconv",
        "sentencepiece>=0.2.0",
    ),
    "mt": ("ctranslate2>=4.0.0", "sentencepiece>=0.2.0", "transformers>=4.40.0"),
    # WhisperSeg only needs onnxruntime + transformers (feature extractor).
    # Do NOT pin numpy<2.5 here — that bound is for FunASR/numba and wrongly
    # triggers reinstalls when SenseVoice already pulled numpy 2.5.x.
    # Prefer CPU/GPU onnxruntime module (either dist); avoid onnxruntime-gpu.
    "vad-whisperseg": (
        "onnxruntime>=1.14.0,<1.22",
        "transformers>=4.40.0",
        # transformers 5.x rejects tokenizers 0.23.1+ at import time
        # (ImportError), which WhisperSeg surfaces as "需要 transformers".
        "tokenizers>=0.22.0,<=0.23.0",
        "numpy>=1.17",
    ),
}

# Optional / unused FunASR model paths — do not auto-pull after --no-deps.
# Also skip transformers CLI niceties (typer/rich/pygments): WhisperSeg only
# imports WhisperFeatureExtractor and does not need the Typer CLI stack.
_SKIP_AUTO_REQUIRES = frozenset(
    {
        "einops",
        "pytorch-wpe",
        "pytorch_wpe",
        "triton",
        "whisper",
        "openai-whisper",
        "cn-tn",
        "cn_tn",
        "tensorboardx",
        "oss2",
        "umap-learn",
        "umap_learn",
        "modelscope",
        "tiktoken",
        "hydra-core",
        "omegaconf",
        "websockets",
        "jamo",
        "rapidfuzz",
        "torch-complex",
        "torch_complex",
        "typer",
        "rich",
        "pygments",
        "markdown-it-py",
        "markdown_it_py",
        "shellingham",
        "click",
    }
)


def _is_skipped_auto_require(dep_name: str) -> bool:
    """True for optional FunASR paths or CUDA stacks handled elsewhere."""
    name = str(dep_name or "").strip().lower().replace("_", "-")
    if not name:
        return True
    if name in _SKIP_AUTO_REQUIRES:
        return True
    # Torch metadata lists nvidia-*-cu12 with Linux markers; never pull the CUDA
    # pip stack here — Windows GPU libs come from ensure_gpu_runtime.
    if name.startswith("nvidia-") or name.startswith("cuda-"):
        return True
    return False


def _requirement_applies_here(req_text: str) -> bool:
    """False when the requirement's environment marker excludes this platform."""
    text = str(req_text or "").strip()
    if not text:
        return False
    try:
        req = Requirement(text)
    except Exception:
        # Fall back to ignoring markers we cannot parse.
        return True
    if req.marker is None:
        return True
    try:
        return bool(req.marker.evaluate())
    except Exception:
        return False


def _bundled_wheels_dir() -> str:
    """transub-engine/wheels next to runtime/ (optional offline find-links)."""
    here = os.path.abspath(os.path.dirname(__file__))
    # .../runtime/Lib/site-packages/transub_engine -> engine root
    engine_root = os.path.abspath(os.path.join(here, "..", "..", "..", ".."))
    candidate = os.path.join(engine_root, "wheels")
    if os.path.isdir(candidate):
        return candidate
    # Dev / alternate layouts
    alt = os.path.abspath(os.path.join(here, "..", "..", "..", "..", "..", "wheels"))
    return candidate if os.path.isdir(candidate) else (alt if os.path.isdir(alt) else "")


def _pip_find_links_args() -> list[str]:
    wheels = _bundled_wheels_dir()
    if not wheels:
        return []
    return ["--find-links", wheels]


def _onnxruntime_importable() -> bool:
    """True when Silero/WhisperSeg can import onnxruntime (CPU or GPU wheel)."""
    try:
        import onnxruntime  # noqa: F401
        return True
    except Exception:
        return False


def _requirement_satisfied(req_str: str) -> bool:
    """True when the distribution is installed and meets the version specifier."""
    text = str(req_str or "").strip()
    if not text:
        return True
    try:
        req = Requirement(text)
    except Exception:
        return False
    name = req.name.lower().replace("_", "-")
    # onnxruntime-gpu also provides the `onnxruntime` module; treat either as OK
    # for Whisper Silero VAD / WhisperSeg so we do not force a conflicting wheel.
    if name in ("onnxruntime", "onnxruntime-gpu") and _onnxruntime_importable():
        # Still honor version pins against whichever dist is installed.
        installed_ver = None
        for cand in ("onnxruntime-gpu", "onnxruntime") if name == "onnxruntime-gpu" else ("onnxruntime", "onnxruntime-gpu"):
            try:
                installed_ver = pkg_version(cand)
                break
            except PackageNotFoundError:
                continue
            except Exception:
                continue
        if installed_ver is None:
            return True
        if req.specifier and installed_ver not in req.specifier:
            return False
        return True
    try:
        installed = pkg_version(req.name)
    except PackageNotFoundError:
        if name == "onnxruntime":
            try:
                installed = pkg_version("onnxruntime-gpu")
            except PackageNotFoundError:
                return False
        else:
            return False
    except Exception:
        return False
    if req.specifier and installed not in req.specifier:
        return False
    return True


def _unsatisfied_packages(packages: Sequence[str]) -> list[str]:
    return [str(p).strip() for p in packages if str(p).strip() and not _requirement_satisfied(p)]


def _unsatisfied_hard_requires(dist_names: Sequence[str]) -> list[str]:
    """
    Missing hard (non-extra) requirements of packages installed with --no-deps.
    Honors environment markers (so Linux-only nvidia-* pins are not pulled on
    Windows) and skips optional / CUDA stacks listed in _SKIP_AUTO_REQUIRES.
    """
    missing: list[str] = []
    seen: set[str] = set()
    for dist in dist_names:
        name = str(dist or "").strip()
        if not name:
            continue
        try:
            reqs = pkg_requires(name) or []
        except PackageNotFoundError:
            try:
                reqs = pkg_requires(name.replace("-", "_")) or []
            except Exception:
                continue
        except Exception:
            continue
        for raw in reqs:
            text = str(raw or "").strip()
            if not text:
                continue
            low = text.lower().replace(" ", "")
            if "extra==" in low:
                continue
            if not _requirement_applies_here(text):
                continue
            try:
                req = Requirement(text)
                dep_name = req.name.lower().replace("_", "-")
                # Install without the marker clause (marker already evaluated).
                base = f"{req.name}{req.specifier}" if req.specifier else req.name
                if req.extras:
                    extras = ",".join(sorted(req.extras))
                    base = f"{req.name}[{extras}]{req.specifier}"
            except Exception:
                base = text.split(";", 1)[0].strip()
                dep_name = (
                    base.split(">", 1)[0]
                    .split("<", 1)[0]
                    .split("=", 1)[0]
                    .split("[", 1)[0]
                    .strip()
                    .lower()
                    .replace("_", "-")
                )
            if _is_skipped_auto_require(dep_name):
                continue
            key = base.lower()
            if key in seen:
                continue
            seen.add(key)
            if _requirement_satisfied(base):
                continue
            missing.append(base)
    return missing


def _uninstall_onnxruntime_cpu_if_present() -> None:
    """Remove CPU onnxruntime so onnxruntime-gpu can take over (mutually exclusive)."""
    try:
        pkg_version("onnxruntime")
    except PackageNotFoundError:
        return
    except Exception:
        return
    _log.info("uninstalling onnxruntime (CPU) before onnxruntime-gpu")
    try:
        _run_pip(["uninstall", "-y", "onnxruntime"], timeout=120)
    except Exception as err:
        _log.warning("onnxruntime uninstall failed: %s", err)


def _is_policy_blocked_error(text: str) -> bool:
    """True when Windows Smart App Control / app control policy blocked a native DLL."""
    t = str(text or "")
    low = t.lower()
    return bool(
        "应用程序控制策略" in t
        or "智能应用控制" in t
        or "smart app" in low
        or "winerror 4551" in low
        or "4551" in t
    )


def _is_dll_load_error(text: str) -> bool:
    t = str(text or "")
    low = t.lower()
    return bool(
        "dll load failed" in low
        or "找不到指定的模块" in t
        or "winerror 126" in low
    )


def probe_asr_whisper() -> dict[str, Any]:
    """Return readiness of Whisper CT2 + Silero VAD stack."""
    missing: list[str] = []
    errors: list[str] = []
    numpy_ver = ""
    fw_ver = ""
    av_ver = ""
    ct2_ver = ""
    ort_ver = ""
    try:
        import numpy as np  # type: ignore

        numpy_ver = str(getattr(np, "__version__", "") or "")
    except Exception as err:
        missing.append("numpy")
        errors.append(f"numpy: {err}")
    try:
        import av  # type: ignore

        av_ver = str(getattr(av, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("av")
        errors.append(f"av: {err}")
    try:
        import ctranslate2 as ct2  # type: ignore

        ct2_ver = str(getattr(ct2, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("ctranslate2")
        errors.append(f"ctranslate2: {err}")
    try:
        import onnxruntime as ort  # type: ignore

        ort_ver = str(getattr(ort, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("onnxruntime")
        errors.append(f"onnxruntime: {err}")
    try:
        import faster_whisper  # type: ignore

        fw_ver = str(getattr(faster_whisper, "__version__", "") or "") or "unknown"
    except Exception as err:
        err_s = str(err)
        if "ctranslate2" in err_s.lower() and "ctranslate2" in missing:
            errors.append(f"faster-whisper: {err_s}")
        else:
            missing.append("faster-whisper")
            errors.append(f"faster-whisper: {err_s}")

    policy_blocked = any(_is_policy_blocked_error(e) for e in errors)
    dll_blocked = (not policy_blocked) and any(_is_dll_load_error(e) for e in errors)
    ready = not missing
    if ready:
        hint = (
            f"Whisper 运行库就绪（faster-whisper {fw_ver or '?'}，"
            f"ctranslate2 {ct2_ver or '?'}，onnxruntime {ort_ver or '?'}，"
            f"av {av_ver or '?'}，numpy {numpy_ver or '?'}）"
        )
    elif policy_blocked:
        hint = (
            "Windows 应用程序控制策略/智能应用控制拦截了 Whisper 依赖 DLL（多为 av）。"
            "关闭该策略或将 transub-engine 目录加入排除后重试；仅重装 pip 包无法解除拦截。"
        )
    elif dll_blocked:
        hint = (
            "无法加载 Whisper 原生依赖 DLL。请先安装 Visual C++ 运行库；"
            "若仍失败请关闭「智能应用控制」后重试。"
        )
    else:
        hint = (
            "未安装 Whisper 运行库（faster-whisper / ctranslate2 / onnxruntime / av / numpy）。"
            "下载 Whisper 模型或一键修复时会自动安装；也可手动执行："
            ' runtime\\python.exe -m pip install "faster-whisper>=1.1.0" "ctranslate2>=4.0.0"'
            ' "onnxruntime>=1.14.0,<1.22" "av>=10.0.0" "numpy>=1.24.0,<2.5"'
        )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else ("policy_blocked" if policy_blocked else "need_install"),
        "installed": ready,
        "fasterWhisperVersion": fw_ver,
        "ctranslate2Version": ct2_ver,
        "onnxruntimeVersion": ort_ver,
        "avVersion": av_ver,
        "numpyVersion": numpy_ver,
        "missing": missing,
        "errors": errors,
        "policyBlocked": policy_blocked,
        "dllBlocked": dll_blocked,
        "hint": hint,
        "packages": list(EXTRA_PACKAGES["asr-whisper"]),
    }


def probe_vad_whisperseg() -> dict[str, Any]:
    """Return readiness of WhisperSeg ONNX stack (import-based)."""
    pkgs = list(EXTRA_PACKAGES["vad-whisperseg"])
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}

    try:
        import onnxruntime as ort  # type: ignore

        versions["onnxruntime"] = str(getattr(ort, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("onnxruntime")
        errors.append(f"onnxruntime: {err}")
        versions["onnxruntime"] = ""

    try:
        import transformers  # type: ignore
        from transformers import WhisperFeatureExtractor  # noqa: F401

        versions["transformers"] = str(getattr(transformers, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("transformers")
        errors.append(f"transformers: {err}")
        versions["transformers"] = ""

    try:
        import tokenizers  # type: ignore

        versions["tokenizers"] = str(getattr(tokenizers, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("tokenizers")
        errors.append(f"tokenizers: {err}")
        versions["tokenizers"] = ""

    try:
        import numpy as np  # type: ignore

        versions["numpy"] = str(getattr(np, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("numpy")
        errors.append(f"numpy: {err}")
        versions["numpy"] = ""

    # Also surface metadata gaps (helps decide which wheels to fetch) without
    # treating a looser-but-importable numpy as a hard failure.
    meta_missing = _unsatisfied_packages(pkgs)
    ready = not missing
    hint = (
        "WhisperSeg 运行库就绪（"
        + "，".join(f"{k} {v or '?'}" for k, v in versions.items())
        + "）"
        if ready
        else (
            "未安装 WhisperSeg 运行库（onnxruntime / transformers / tokenizers / numpy）。"
            "下载 whisperseg-asmr 时会自动安装。"
        )
    )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else "need_install",
        "installed": ready,
        "missing": missing or meta_missing,
        "metaMissing": meta_missing,
        "errors": errors,
        "versions": versions,
        "hint": hint,
        "packages": pkgs,
    }


def extras_for_model_ids(model_ids: Iterable[str] | None) -> list[str]:
    """Map catalog model ids → pip extra keys needed to run them."""
    needed: list[str] = []
    seen: set[str] = set()

    def add(key: str) -> None:
        if key in seen:
            return
        seen.add(key)
        needed.append(key)

    for mid in model_ids or []:
        mid_s = str(mid or "").strip()
        if not mid_s:
            continue
        spec = get_spec(mid_s)
        backend = str(getattr(spec, "backend", "") or "").lower() if spec else ""
        kind = str(getattr(spec, "kind", "") or "").lower() if spec else ""
        low = mid_s.lower()

        if "whisperseg" in low or backend == "whisperseg":
            add("vad-whisperseg")
        if kind == "mt" or backend in ("opus-ct2", "marian") or low.startswith("opus-mt-"):
            add("mt")
        if "sensevoice" in low or backend == "sensevoice":
            add("asr-sensevoice")
        if "whisper" in low or backend == "whisper":
            # LID + Whisper ASR (exclude whisperseg-only ids already handled)
            if "whisperseg" not in low:
                add("asr-whisper")

    return needed


def _unit_to_bytes(value: float, unit: str) -> int:
    mul = _UNIT_BYTES.get(str(unit or "b").lower(), 1.0)
    try:
        return max(0, int(float(value) * mul))
    except (TypeError, ValueError):
        return 0


def _run_pip(args: list[str], *, timeout: int = 3600) -> subprocess.CompletedProcess[str]:
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("runtime_extras pip: %s", " ".join(cmd))
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout,
        check=False,
    )


def _parse_pip_progress_line(line: str) -> dict[str, Any] | None:
    text = str(line or "").strip()
    if not text:
        return None
    m_dl = _RE_DOWNLOADING.search(text)
    if m_dl:
        name = m_dl.group(1)
        total = _unit_to_bytes(float(m_dl.group(2)), m_dl.group(3))
        return {
            "package": name,
            "downloadedBytes": 0,
            "totalBytes": total or None,
            "bytesPerSecond": None,
        }
    m_pg = _RE_PROGRESS.search(text)
    if m_pg:
        cur = _unit_to_bytes(float(m_pg.group(1)), m_pg.group(3))
        total = _unit_to_bytes(float(m_pg.group(2)), m_pg.group(3))
        speed = None
        if m_pg.group(4) and m_pg.group(5):
            speed = float(_unit_to_bytes(float(m_pg.group(4)), m_pg.group(5)))
        return {
            "downloadedBytes": cur,
            "totalBytes": total or None,
            "bytesPerSecond": speed,
        }
    return None


def _run_pip_with_progress(
    args: list[str],
    *,
    on_progress: ProgressCb | None,
    label: str,
    host: str,
    timeout: int = 3600,
    stall_sec: float = DOWNLOAD_STALL_SEC,
    resolve_stall_sec: float = PIP_RESOLVE_STALL_SEC,
) -> subprocess.CompletedProcess[str]:
    """
    Stream pip stdout/stderr so wheel download size/speed can be reported.
    Aborts the mirror when byte progress stalls (so callers can switch sources).
    """
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("runtime_extras pip: %s", " ".join(cmd))
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    env.setdefault("PIP_PROGRESS_BAR", "on")
    env.setdefault("PIP_DISABLE_PIP_VERSION_CHECK", "1")
    env.setdefault("PIP_DEFAULT_TIMEOUT", "120")

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            bufsize=1,
        )
    except OSError as err:
        return subprocess.CompletedProcess(cmd, 1, "", str(err))

    chunks: list[str] = []
    buf = ""
    current_pkg = ""
    last_emit = 0.0
    started = time.monotonic()
    state = {
        "download_started": False,
        "last_progress_at": started,
        "last_downloaded": -1,
        "stalled": False,
    }
    stop_watch = threading.Event()

    def flush_token(token: str) -> None:
        nonlocal current_pkg, last_emit
        token = token.strip()
        if not token:
            return
        chunks.append(token + "\n")
        parsed = _parse_pip_progress_line(token)
        if not parsed:
            return
        if parsed.get("package"):
            current_pkg = str(parsed["package"])
            state["download_started"] = True
            # New package line is progress once; subsequent redraws need byte growth.
            if current_pkg != state.get("_last_pkg"):
                state["_last_pkg"] = current_pkg
                state["last_progress_at"] = time.monotonic()
        downloaded = parsed.get("downloadedBytes")
        total = parsed.get("totalBytes")
        speed = parsed.get("bytesPerSecond")
        if isinstance(downloaded, (int, float)) and int(downloaded) > int(state["last_downloaded"]):
            state["last_downloaded"] = int(downloaded)
            state["last_progress_at"] = time.monotonic()
            state["download_started"] = True
        now = time.monotonic()
        pkg_changed = bool(parsed.get("package"))
        if not pkg_changed and (now - last_emit) < 0.45:
            return
        last_emit = now
        detail = f"正在安装{label}（{host}）"
        if current_pkg:
            short = current_pkg.rsplit("/", 1)[-1]
            if len(short) > 48:
                short = short[:45] + "…"
            detail = f"{detail} · {short}"
        payload: dict[str, Any] = {
            "type": "progress",
            "stage": "pip",
            "detail": detail,
            "mirror": host,
        }
        if isinstance(downloaded, (int, float)) and downloaded >= 0:
            payload["downloadedBytes"] = int(downloaded)
        if isinstance(total, (int, float)) and total > 0:
            payload["totalBytes"] = int(total)
        if isinstance(speed, (int, float)) and speed > 0:
            payload["bytesPerSecond"] = float(speed)
            if speed < 80_000 and isinstance(downloaded, (int, float)) and downloaded > 2 * 1024 * 1024:
                payload["suggestManual"] = True
        emit(payload)

    def consume_buf() -> None:
        nonlocal buf
        while True:
            cut = -1
            for sep in ("\r", "\n"):
                idx = buf.find(sep)
                if idx >= 0 and (cut < 0 or idx < cut):
                    cut = idx
            if cut < 0:
                return
            token = buf[:cut]
            buf = buf[cut + 1 :]
            flush_token(token)

    def _stall_message() -> str:
        if state["download_started"]:
            return f"STALL: 下载停滞超过 {int(stall_sec)} 秒（镜像 {host}）"
        return f"STALL: 解析/连接停滞超过 {int(resolve_stall_sec)} 秒（镜像 {host}）"

    def _watch_stall() -> None:
        while not stop_watch.wait(2.0):
            now = time.monotonic()
            elapsed = now - started
            session_bytes = max(0, int(state["last_downloaded"]))
            if not state["download_started"]:
                # Keep UI alive during long pip resolve (otherwise the last
                # "正在安装…（mirror）" line looks hung).
                emit(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": (
                            f"正在解析/连接{label}（{host}）…"
                            f"已 {int(elapsed)} 秒，超时将自动换镜像"
                        ),
                        "mirror": host,
                        "suggestManual": elapsed >= max(20.0, resolve_stall_sec * 0.6),
                    }
                )
            if state["download_started"]:
                reason = transfer_should_abort(
                    elapsed_sec=elapsed,
                    session_bytes=session_bytes if session_bytes > 0 else 0,
                    last_progress_age_sec=now - float(state["last_progress_at"]),
                    stall_sec=stall_sec,
                )
            else:
                reason = (
                    f"STALL: 解析/连接停滞超过 {int(resolve_stall_sec)} 秒"
                    if (now - float(state["last_progress_at"])) > resolve_stall_sec
                    else None
                )
            if not reason:
                continue
            state["stalled"] = True
            state["stall_reason"] = reason
            try:
                proc.kill()
            except Exception:
                pass
            return

    watch = threading.Thread(target=_watch_stall, name=f"pip-stall-{host}", daemon=True)
    watch.start()
    try:
        assert proc.stdout is not None
        while True:
            now = time.monotonic()
            if timeout > 0 and (now - started) > timeout:
                proc.kill()
                try:
                    proc.wait(timeout=5)
                except Exception:
                    pass
                raise subprocess.TimeoutExpired(cmd, timeout)
            if state["stalled"]:
                break
            block = proc.stdout.read(4096)
            if not block:
                break
            # Do NOT reset stall timer on arbitrary stdout — pip can spam the same
            # progress line forever while the socket is hung.
            buf += block
            consume_buf()
        if buf.strip():
            flush_token(buf)
            buf = ""
        if state["stalled"]:
            msg = str(state.get("stall_reason") or _stall_message())
            chunks.append(msg + "\n")
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"{host} 过慢/停滞，自动切换下一镜像…",
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            return subprocess.CompletedProcess(cmd, 1, "".join(chunks), msg)
        returncode = proc.wait(timeout=30)
    except subprocess.TimeoutExpired:
        raise
    except Exception as err:
        try:
            proc.kill()
        except Exception:
            pass
        return subprocess.CompletedProcess(cmd, 1, "".join(chunks), str(err))
    finally:
        stop_watch.set()
        try:
            watch.join(timeout=1.0)
        except Exception:
            pass

    combined = "".join(chunks)
    return subprocess.CompletedProcess(cmd, returncode, combined, "")


def _req_base_name(req_str: str) -> str:
    text = str(req_str or "").strip()
    if not text:
        return ""
    try:
        return Requirement(text).name.lower().replace("_", "-")
    except Exception:
        return (
            text.split(">", 1)[0]
            .split("<", 1)[0]
            .split("=", 1)[0]
            .split("[", 1)[0]
            .strip()
            .lower()
            .replace("_", "-")
        )


def _followup_nodeps_requires(
    installed_reqs: Sequence[str],
    *,
    index_url: str,
    host: str,
    on_progress: ProgressCb | None,
    label: str,
) -> dict[str, Any]:
    """
    After --no-deps wheel installs, pip-install any still-missing hard requires.
    Returns {"ok": True, "installed": [...]} or a failure dict.
    """
    parents = [_req_base_name(p) for p in installed_reqs if str(p).strip()]
    unmet = _unsatisfied_hard_requires(parents)
    # Deduplicate while preserving order
    seen: set[str] = set()
    ordered: list[str] = []
    for u in unmet:
        key = u.lower()
        if key in seen:
            continue
        seen.add(key)
        ordered.append(u)
    if not ordered:
        return {"ok": True, "installed": []}

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    emit(
        {
            "type": "progress",
            "stage": "pip",
            "detail": f"补齐{label}传递依赖（{len(ordered)} 个，因离线包装用了 --no-deps）…",
            "packages": ordered,
            "mirror": host,
        }
    )
    args = [
        "install",
        "--prefer-binary",
        "--only-binary=numba,llvmlite",
        *(_pip_find_links_args()),
        "-i",
        index_url,
        "--trusted-host",
        host,
        *ordered,
    ]
    try:
        proc = _run_pip_with_progress(
            args,
            on_progress=on_progress,
            label=f"{label} deps",
            host=host,
        )
    except Exception as err:
        return {
            "ok": False,
            "code": "EXTRAS_INSTALL_FAILED",
            "message": f"补齐{label}传递依赖失败：{err}",
            "packages": ordered,
        }
    if proc.returncode != 0:
        err = (proc.stdout or "")[-2000:] or (proc.stderr or "")[-2000:] or "pip failed"
        return {
            "ok": False,
            "code": "EXTRAS_INSTALL_FAILED",
            "message": f"补齐{label}传递依赖失败：{err}",
            "packages": ordered,
        }
    return {"ok": True, "installed": ordered}


def _install_packages(
    packages: tuple[str, ...] | list[str],
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
    label: str = "依赖",
) -> dict[str, Any]:
    requested = [str(p).strip() for p in packages if str(p).strip()]
    if not requested:
        return {"ok": True, "installed": [], "skipped": True}

    # Avoid `pip install --upgrade` on already-satisfied pins: mirrors (esp.
    # Tsinghua) often 403 on newest wheels even when the installed version is fine.
    pkgs = list(requested) if force else _unsatisfied_packages(requested)
    if not pkgs:
        return {
            "ok": True,
            "installed": [],
            "skipped": True,
            "reason": "already_satisfied",
            "packages": requested,
        }

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    emit(
        {
            "type": "progress",
            "stage": "pip",
            "detail": f"正在测速 PyPI 镜像（索引 + 包文件吞吐，共 {len(PIP_MIRRORS)} 个）…",
            "packages": pkgs,
        }
    )
    probe_rows = probe_pip_mirrors()
    mirrors = order_pip_mirrors(probe_rows)
    probe_summary = format_probe_summary(probe_rows)
    best = mirrors[0][1] if mirrors else ""
    best_bps = best_probe_bytes_per_sec(probe_rows)
    best_speed = format_bytes_per_sec(best_bps)
    suggest = bool(best_bps > 0 and best_bps < 80_000)
    emit(
        {
            "type": "progress",
            "stage": "pip",
            "detail": (
                f"镜像测速完成，优先使用 {best}"
                + (f"（约 {best_speed}）" if best_speed else "")
                + (f"；{probe_summary}" if probe_summary else "")
                + ("。吞吐较低，若卡住请改用手动下载" if suggest else "")
            ),
            "packages": pkgs,
            "mirror": best,
            "mirrorProbe": probe_rows,
            "suggestManual": suggest,
        }
    )

    known_pkgs = [p for p in pkgs if known_wheel_rel(_req_base_name(p))]
    other_pkgs = [p for p in pkgs if p not in known_pkgs]

    last_err = ""
    tried: list[str] = []
    for index_url, host in mirrors:
        tried.append(host)
        local_paths: list[str] = []

        # Large known wheels: resumable HTTP download, then offline local pip install.
        if known_pkgs:
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "detail": f"正在直链下载运行库（{host}，可断点续传）…",
                    "packages": known_pkgs,
                    "mirror": host,
                }
            )
            dl = download_known_wheels(
                known_pkgs,
                index_url=index_url,
                host=host,
                on_progress=on_progress,
                detail_prefix=f"下载{label}",
            )
            if not dl.get("ok"):
                last_err = str(dl.get("error") or "直链下载失败")
                stalled = bool(dl.get("stalled"))
                if is_mirror_http_deny(last_err):
                    note_mirror_denied(host)
                emit(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": (
                            f"{host} {'下载停滞' if stalled else '直链失败'}，自动切换下一镜像…"
                        ),
                        "packages": pkgs,
                        "mirror": host,
                        "suggestManual": True,
                    }
                )
                continue
            local_paths = list(dl.get("localPaths") or [])

        if local_paths and not other_pkgs:
            from .pip_mirror_util import install_local_wheel_files

            inst = install_local_wheel_files(
                local_paths,
                on_progress=on_progress,
                detail_prefix=f"安装{label}",
            )
            if inst.get("ok"):
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                if not follow.get("ok"):
                    return {
                        **follow,
                        "mirrorsTried": tried,
                        "mirrorProbe": probe_rows,
                        "suggestManual": True,
                    }
                emit(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": f"已安装{label}（{host}，离线）",
                        "packages": pkgs,
                        "mirror": host,
                    }
                )
                return {
                    "ok": True,
                    "installed": pkgs,
                    "depsInstalled": follow.get("installed") or [],
                    "mirror": host,
                    "mirrorProbe": probe_rows,
                    "method": "direct-whl",
                }
            # Offline install failed — wheels are local; do not keep re-downloading.
            last_err = str(inst.get("error") or "本地安装失败")
            return {
                "ok": False,
                "code": inst.get("code") or "EXTRAS_INSTALL_FAILED",
                "message": (
                    f"安装{label}失败：{last_err}。"
                    "文件已在本地缓存，可重试或改用「手动下载安装」。"
                ),
                "packages": pkgs,
                "mirrorsTried": tried,
                "mirrorProbe": probe_rows,
                "suggestManual": True,
                "logTail": str(inst.get("logTail") or "")[-800:],
            }

        install_targets = [*local_paths, *other_pkgs]
        if not install_targets:
            continue

        args = [
            "install",
            "--prefer-binary",
            "--only-binary=numba,llvmlite",
            *(_pip_find_links_args()),
            "-i",
            index_url,
            "--trusted-host",
            host,
            *install_targets,
        ]
        if force:
            args.insert(1, "--upgrade")
            args.insert(2, "--force-reinstall")
        # Prefer offline install for any local wheel paths mixed into the command.
        if local_paths:
            # Install cached wheels offline first, then remaining index packages.
            from .pip_mirror_util import install_local_wheel_files as _inst_local

            inst = _inst_local(
                local_paths,
                on_progress=on_progress,
                detail_prefix=f"安装{label}",
            )
            if not inst.get("ok"):
                last_err = str(inst.get("error") or "本地安装失败")
                return {
                    "ok": False,
                    "code": inst.get("code") or "EXTRAS_INSTALL_FAILED",
                    "message": (
                        f"安装{label}失败：{last_err}。"
                        "已下载的 wheel 仍在缓存，可重试或改用手动安装。"
                    ),
                    "packages": pkgs,
                    "mirrorsTried": tried,
                    "mirrorProbe": probe_rows,
                    "suggestManual": True,
                    "logTail": str(inst.get("logTail") or "")[-800:],
                }
            if not other_pkgs:
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                if not follow.get("ok"):
                    return {
                        **follow,
                        "mirrorsTried": tried,
                        "mirrorProbe": probe_rows,
                        "suggestManual": True,
                    }
                return {
                    "ok": True,
                    "installed": pkgs,
                    "depsInstalled": follow.get("installed") or [],
                    "mirror": host,
                    "mirrorProbe": probe_rows,
                    "method": "direct-whl",
                }
            args = [
                "install",
                "--prefer-binary",
                "--only-binary=numba,llvmlite",
                *(_pip_find_links_args()),
                "-i",
                index_url,
                "--trusted-host",
                host,
                *other_pkgs,
            ]
            if force:
                args.insert(1, "--upgrade")
                args.insert(2, "--force-reinstall")
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": f"正在安装{label}（{host}）…",
                "packages": pkgs,
                "mirror": host,
            }
        )
        try:
            proc = _run_pip_with_progress(
                args,
                on_progress=on_progress,
                label=label,
                host=host,
                timeout=3600,
            )
        except subprocess.TimeoutExpired:
            last_err = f"安装{label}超时（镜像 {host}）"
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"{host} 超时，自动切换下一镜像…",
                    "packages": pkgs,
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            continue
        if proc.returncode == 0:
            follow: dict[str, Any] = {"ok": True, "installed": []}
            if local_paths:
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                if not follow.get("ok"):
                    return {
                        **follow,
                        "mirrorsTried": tried,
                        "mirrorProbe": probe_rows,
                        "suggestManual": True,
                    }
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"已安装{label}（{host}）",
                    "packages": pkgs,
                    "mirror": host,
                }
            )
            return {
                "ok": True,
                "installed": pkgs,
                "depsInstalled": follow.get("installed") or [],
                "mirror": host,
                "mirrorProbe": probe_rows,
            }
        last_err = (proc.stderr or proc.stdout or "").strip()[-1200:] or f"exit {proc.returncode}"
        denied = is_mirror_http_deny(last_err)
        if denied:
            note_mirror_denied(host)
        _log.warning(
            "pip install failed via %s%s: %s",
            host,
            " (HTTP deny/stall)" if denied else "",
            last_err[:400],
        )
        reason = "返回 403/停滞" if denied else "安装失败"
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": f"{host} {reason}，自动切换下一镜像…",
                "packages": pkgs,
                "mirror": host,
                "mirrorDenied": denied,
                "suggestManual": True,
            }
        )

    tried_s = " → ".join(tried) if tried else "无"
    hint = " 可改用应用内「手动下载安装」，用浏览器下载 .whl 后本地安装。"
    low = last_err.lower()
    if "numba" in low and ("failed to build" in low or "getting requirements to build" in low):
        hint = (
            " 提示：请使用 numpy<2.5 的预编译包（推荐 2.4.x）；"
            "不要安装 numpy 2.5+，否则 numba 会尝试源码编译并失败。"
        ) + hint
    return {
        "ok": False,
        "code": "EXTRAS_INSTALL_FAILED",
        "message": f"安装{label}失败（已尝试镜像：{tried_s}）。{last_err}{hint}",
        "packages": pkgs,
        "mirrorsTried": tried,
        "mirrorProbe": probe_rows,
        "suggestManual": True,
    }


def _whisper_native_modules_loaded() -> bool:
    """True when Whisper native deps are already imported in this process."""
    import sys

    return any(
        name in sys.modules
        for name in ("ctranslate2", "onnxruntime", "av", "numpy", "faster_whisper")
    )


def ensure_asr_whisper(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure faster-whisper + ctranslate2 + av + numpy for Whisper ASR / short-window LID."""
    # Prefer metadata / import checks before any --force-reinstall. Importing
    # native wheels then rewriting them in the same process fails on Windows
    # with WinError 5 (DLL still mapped).
    unsatisfied = _unsatisfied_packages(EXTRA_PACKAGES["asr-whisper"])
    loaded = _whisper_native_modules_loaded()

    if not unsatisfied and (not force or loaded):
        probe = probe_asr_whisper()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
        if probe.get("policyBlocked"):
            return {
                **probe,
                "ok": False,
                "code": "SMART_APP_CONTROL",
                "message": str(probe.get("hint") or "应用程序控制策略拦截了 Whisper 依赖 DLL"),
            }
        if loaded or _whisper_native_modules_loaded():
            return {
                **probe,
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    "Whisper 运行库已加载于当前引擎进程，无法原地重装（Windows 会拒绝覆盖 DLL）。"
                    "请停止引擎后重试一键修复，或改用「手动安装」。"
                ),
            }
        use_force = True
    elif unsatisfied:
        use_force = False
    else:
        # force=True, metadata satisfied, nothing imported yet (offline CLI repair).
        use_force = True

    result = _install_packages(
        EXTRA_PACKAGES["asr-whisper"],
        force=use_force,
        on_progress=on_progress,
        label=" Whisper 运行库",
    )
    if not result.get("ok"):
        return result

    probe2 = probe_asr_whisper()
    if not probe2.get("ready"):
        if probe2.get("policyBlocked"):
            return {
                **probe2,
                "ok": False,
                "code": "SMART_APP_CONTROL",
                "message": str(probe2.get("hint") or "应用程序控制策略拦截了 Whisper 依赖 DLL"),
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
            }
        return {
            **probe2,
            "ok": False,
            "code": "ASR_WHISPER_VERIFY_FAILED",
            "message": (
                "已尝试安装 faster-whisper / ctranslate2 / onnxruntime / av / numpy，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
        }
    return {"ok": True, **probe2, "installed": result.get("installed") or [], "mirror": result.get("mirror")}


def ensure_vad_whisperseg(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure onnxruntime + transformers + numpy for WhisperSeg VAD."""
    probe = probe_vad_whisperseg()
    if probe.get("ready"):
        # Import works — skip pip entirely (avoids re-pulling typer/rich/pygments
        # and hanging on mirrors when the stack is already bundled).
        return {
            "ok": True,
            **probe,
            "skipped": True,
            "reason": "already_ready" if force else "already_satisfied",
        }

    unsatisfied = list(probe.get("metaMissing") or []) or _unsatisfied_packages(
        EXTRA_PACKAGES["vad-whisperseg"]
    )
    # Prefer installing only metadata gaps; never force-reinstall a working import stack.
    use_force = not bool(unsatisfied)
    result = _install_packages(
        EXTRA_PACKAGES["vad-whisperseg"] if use_force else unsatisfied or EXTRA_PACKAGES["vad-whisperseg"],
        force=use_force,
        on_progress=on_progress,
        label=" vad-whisperseg",
    )
    if not result.get("ok"):
        return result

    probe2 = probe_vad_whisperseg()
    if not probe2.get("ready"):
        return {
            "ok": False,
            "code": "VAD_WHISPERSEG_VERIFY_FAILED",
            "message": (
                "已尝试安装 onnxruntime / transformers / tokenizers / numpy，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            **probe2,
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
        "skipped": bool(result.get("skipped")),
    }


def probe_asr_sensevoice() -> dict[str, Any]:
    """Return readiness of SenseVoice / FunASR runtime stack (import-based)."""
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}
    for mod_name, key in (
        ("numpy", "numpy"),
        ("numba", "numba"),
        ("scipy", "scipy"),
        ("librosa", "librosa"),
        ("torch", "torch"),
        ("funasr", "funasr"),
    ):
        try:
            mod = __import__(mod_name)
            versions[key] = str(getattr(mod, "__version__", "") or "") or "ok"
        except Exception as err:
            missing.append(key)
            errors.append(f"{key}: {err}")
            versions[key] = ""
    ready = not missing
    if ready:
        hint = (
            f"SenseVoice 运行库就绪（torch {versions.get('torch') or '?'}，"
            f"funasr {versions.get('funasr') or '?'}，"
            f"numba {versions.get('numba') or '?'}，scipy {versions.get('scipy') or '?'}）"
        )
    else:
        hint = (
            "未安装 SenseVoice 运行库（torch / funasr / numba / scipy / librosa / numpy）。"
            "下载 SenseVoice 模型或一键修复时会自动安装。"
        )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else "need_install",
        "installed": ready,
        "versions": versions,
        "missing": missing,
        "errors": errors,
        "hint": hint,
        "packages": list(EXTRA_PACKAGES["asr-sensevoice"]),
    }


def ensure_asr_sensevoice(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure FunASR SenseVoice deps (torch / numba / scipy / …)."""
    unsatisfied = _unsatisfied_packages(EXTRA_PACKAGES["asr-sensevoice"])
    if not unsatisfied and not force:
        probe = probe_asr_sensevoice()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
    result = _install_packages(
        EXTRA_PACKAGES["asr-sensevoice"],
        force=force and not unsatisfied,
        on_progress=on_progress,
        label=" SenseVoice 运行库",
    )
    if not result.get("ok"):
        return result
    probe2 = probe_asr_sensevoice()
    if not probe2.get("ready"):
        return {
            **probe2,
            "ok": False,
            "code": "ASR_SENSEVOICE_VERIFY_FAILED",
            "message": (
                "已尝试安装 SenseVoice 运行库，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
    }


def probe_mt() -> dict[str, Any]:
    """Return readiness of Opus-MT stack (ctranslate2 + transformers)."""
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}
    for mod_name, key in (
        ("ctranslate2", "ctranslate2"),
        ("transformers", "transformers"),
        ("sentencepiece", "sentencepiece"),
    ):
        try:
            mod = __import__(mod_name)
            versions[key] = str(getattr(mod, "__version__", "") or "") or "ok"
        except Exception as err:
            missing.append(key)
            errors.append(f"{key}: {err}")
            versions[key] = ""
    ready = not missing
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else "need_install",
        "installed": ready,
        "versions": versions,
        "missing": missing,
        "errors": errors,
        "hint": (
            "Opus MT 运行库就绪"
            if ready
            else "未安装 Opus MT 运行库（ctranslate2 / transformers / sentencepiece）。下载翻译模型时会自动安装。"
        ),
        "packages": list(EXTRA_PACKAGES["mt"]),
    }


def ensure_mt(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure ctranslate2 + transformers + sentencepiece for Opus MT."""
    unsatisfied = _unsatisfied_packages(EXTRA_PACKAGES["mt"])
    if not unsatisfied and not force:
        probe = probe_mt()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
    result = _install_packages(
        EXTRA_PACKAGES["mt"],
        force=force and not unsatisfied,
        on_progress=on_progress,
        label=" Opus MT 运行库",
    )
    if not result.get("ok"):
        return result
    probe2 = probe_mt()
    if not probe2.get("ready"):
        return {
            **probe2,
            "ok": False,
            "code": "MT_VERIFY_FAILED",
            "message": (
                "已尝试安装 Opus MT 运行库，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
    }


def ensure_extras_for_models(
    model_ids: Iterable[str] | None,
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Install pip extras required by the given catalog model ids."""
    keys = extras_for_model_ids(model_ids)
    if not keys:
        return {"ok": True, "extras": [], "results": [], "skipped": True}

    results: list[dict[str, Any]] = []
    for key in keys:
        if key == "asr-whisper":
            one = ensure_asr_whisper(force=force, on_progress=on_progress)
        elif key == "vad-whisperseg":
            one = ensure_vad_whisperseg(force=force, on_progress=on_progress)
        elif key == "asr-sensevoice":
            one = ensure_asr_sensevoice(force=force, on_progress=on_progress)
        elif key == "mt":
            one = ensure_mt(force=force, on_progress=on_progress)
        else:
            pkgs = EXTRA_PACKAGES.get(key) or ()
            one = _install_packages(
                pkgs,
                force=force,
                on_progress=on_progress,
                label=f" {key}",
            )
            # Soft-verify only for whisper / whisperseg; other stacks are large
            # and probed at job time.
        results.append({"extra": key, **one})
        if not one.get("ok"):
            # Policy blocks on Whisper (av DLL) must not abort SenseVoice / other extras.
            if one.get("code") == "SMART_APP_CONTROL" and key == "asr-whisper":
                continue
            return {
                "ok": False,
                "code": one.get("code") or "EXTRAS_INSTALL_FAILED",
                "message": one.get("message") or f"安装 {key} 失败",
                "extras": keys,
                "results": results,
            }

    soft_policy = [
        r for r in results
        if r.get("extra") == "asr-whisper" and r.get("code") == "SMART_APP_CONTROL"
    ]
    out: dict[str, Any] = {"ok": True, "extras": keys, "results": results}
    if soft_policy:
        out["warnings"] = soft_policy
        out["message"] = soft_policy[0].get("message") or soft_policy[0].get("hint")
    return out
